SourceCode.Declaration:
/// <summary>
/// Provides activities and activity contexts for inventory instrumentation logging.
/// </summary>
internal final class METInventInstrumentationLogger
{
    private const str InstrumentationNamespace = 'Inventory';
    protected SysInstrumentationLogger instrumentationLogger;
    private METInventInventoryDataServiceInstrumentationActivities inventInventoryDataServiceInstrumentationActivities;
    private METInventInventoryDataServiceDiagnosticToolActivities inventInventoryDataServiceDiagnosticToolActivities;
    private METInventOnhandItemInstrumentationActivities          inventOnhandItemInstrumentationActivities;

}

Method.Source:
/// <summary>
/// /// Initializes a new instance of the METInventInstrumentationLogger class with the specified name.
/// </summary>
/// <param name = "_name">str</param>
private void new(str _name)
{
    instrumentationLogger = SysInstrumentationLoggerFactory::CreateLogger(_name);
}

/// <summary>
/// /// Initializes a new instance of the METInventInstrumentationLogger class with the specified name and custom properties.
/// </summary>
/// <param name = "_activity">SysInstrumentationActivity</param>
/// <returns>SysInstrumentationActivityContext</returns>
internal final SysInstrumentationActivityContext activityContext(SysInstrumentationActivity _activity)
{
    return instrumentationLogger.activityContextWithCustomProperties(_activity);
}

/// <summary>
/// /// Creates a new SysInstrumentationActivity with the specified activity name and the Inventory namespace.
/// </summary>
/// <param name = "_activityName">str</param>
/// <returns>SysInstrumentationActivity</returns>
internal final SysInstrumentationActivity activity(str _activityName)
{
    return SysInstrumentationActivity::construct(_activityName, InstrumentationNamespace);
}

/// <summary>
/// /// Creates a new SysInstrumentationActivity with the specified activity name, the Inventory namespace, and custom properties.
/// </summary>
/// <returns>METInventInstrumentationLoggerProperties</returns>
internal final METInventInstrumentationLoggerProperties properties()
{
    return METInventInstrumentationLoggerProperties::construct();
}

/// <summary>
/// /// Logs the information about the record specified by the Common parameter.
/// </summary>
/// <param name = "_common">Common</param>
internal final void logRecordInformation(Common _common)
{
    instrumentationLogger.logInformation(strFmt('%1:%2', tableId2Name(_common.TableId), _common.RecId));
}

/// <summary>
/// /// Creates a new instance of the METInventInstrumentationLogger class with the specified name.
/// </summary>
/// <param name = "_name">str</param>
/// <returns>METInventInstrumentationLogger</returns>
internal static METInventInstrumentationLogger createLogger(str _name)
{
    return new METInventInstrumentationLogger(_name);
}

/// <summary>
/// logs the information message specified by the _message parameter.
/// </summary>
/// <param name = "_message">str</param>
internal final void logInformation(str _message)
{
    instrumentationLogger.logInformation(_message);
}

/// <summary>
/// /// Logs the warning message specified by the _message parameter.
/// </summary>
/// <param name = "_message">str</param>
internal final void logWarning(str _message)
{
    instrumentationLogger.logWarning(_message);
}

/// <summary>
/// //// Logs the error message specified by the _message parameter.
/// </summary>
/// <param name = "_message">str</param>
final internal void logError(str _message)
{
    instrumentationLogger.logError(_message);
}

/// <summary>
/// /// Logs the exception specified by the _exception parameter and the message specified by the _message parameter.
/// </summary>
/// <param name = "_exception">System.Exception</param>
/// <param name = "_message">str</param>
final internal void logException(System.Exception _exception, str _message)
{
    instrumentationLogger.logException(_exception, _message);
}

/// <summary>
/// Logs the current stack trace.
/// </summary>
/// <remarks>Only use in failure scenarios and under a flight, as building the stack trace is time consuming.</remarks>
internal final void logStackTrace()
{
    instrumentationLogger.logInformation(strFmt('StackTrace: %1', new System.Diagnostics.StackTrace().ToString()));
}

/// <summary>
/// /// Gets the inventory data service instrumentation activities.
/// </summary>
/// <returns>METInventInventoryDataServiceInstrumentationActivities</returns>
final internal METInventInventoryDataServiceInstrumentationActivities getInventoryDataServiceActivity()
{
    if (!inventInventoryDataServiceInstrumentationActivities)
    {
        inventInventoryDataServiceInstrumentationActivities = METInventInventoryDataServiceInstrumentationActivities::newFromLogger(this);
    }

    return inventInventoryDataServiceInstrumentationActivities;
}

/// <summary>
/// /// Gets the inventory data service diagnostic tool activities.
/// </summary>
/// <returns>METInventInventoryDataServiceDiagnosticToolActivities</returns>
final internal METInventInventoryDataServiceDiagnosticToolActivities getInventoryServiceDiagnosticToolActivities()
{
    if (!inventInventoryDataServiceDiagnosticToolActivities)
    {
        inventInventoryDataServiceDiagnosticToolActivities = METInventInventoryDataServiceDiagnosticToolActivities::newFromLogger(this);
    }

    return inventInventoryDataServiceDiagnosticToolActivities;
}

/// <summary>
/// /// Gets the on-hand item instrumentation activities.
/// </summary>
/// <returns>METInventOnhandItemInstrumentationActivities</returns>
final internal METInventOnhandItemInstrumentationActivities inventOnhandItem()
{
    if (!inventOnhandItemInstrumentationActivities)
    {
        inventOnhandItemInstrumentationActivities = METInventOnhandItemInstrumentationActivities::newFromLogger(this);
    }

    return inventOnhandItemInstrumentationActivities;
}
